css:
@font-face {
	font-family: "THSarabun";
	src: url("/assets/erpnext_thailand/fonts/THSarabun.ttf");
}

@page {
	margin: 0;
}
/* ปลดล็อค height และ overflow ออกเพื่อให้ขึ้นหน้า 2 ได้ */
html,
body {
	margin: 0;
	padding: 0;
}

.print-format {
	padding: 0 !important;
	margin: 0 !important;
	margin-top: 0mm !important;
	margin-bottom: 0mm !important;
	margin-left: 0mm !important;
	margin-right: 0mm !important;
	min-height: 0 !important;
	max-width: none !important;
}

.print-format-preview {
	padding: 0 !important;
}

/* ── Base ── */
.page {
	position: relative;
	width: 210mm;
	height: 280mm;
	background-image: url("/assets/connect_diagnostics_core/images/print_formats/cd_purchase_orders.jpg?v=20260603-jpgpdf1");
	background-size: 100% 100%;
	background-repeat: no-repeat;
	font-family: "THSarabun", "Sarabun", Arial, sans-serif;
	font-weight: 400;
	color: #575858;
	overflow: hidden; /* คำสั่งนี้อยู่ที่กรอบแต่ละหน้าแทน เพื่อไม่ให้ของล้นออกนอกแผ่น */
	page-break-after: always;
}
.page.last-page {
	page-break-after: auto;
}
.f {
	position: absolute;
	font-family: "THSarabun", "Sarabun", Arial, sans-serif;
	font-weight: 400;
	line-height: 1.2;
}
.tr {
	text-align: right;
}
.tc {
	text-align: center;
}

.copy-label {
	top: 42mm;
	left: 132mm;
	width: 47mm;
	font-size: 12pt;
}

.company-address {
	top: 21.2mm;
	left: 34.4mm;
	width: 76.7mm;
	font-size: 10pt;
	line-height: 1.12;
}

/* ── Supplier Info ── */
.supplier-code {
	top: 53mm;
	left: 30mm;
	width: 91mm;
	font-size: 8.5pt;
}
.party-name {
	top: 60mm;
	left: 18mm;
	width: 91mm;
	font-size: 8.5pt;
}
.party-address {
	top: 64mm;
	left: 18mm;
	width: 91mm;
	font-size: 8.5pt;
}
.party-mobile {
	top: 81mm;
	left: 28mm;
	font-size: 10pt;
}
.reference {
	top: 88mm;
	left: 28mm;
	font-size: 10pt;
}

/* ── PO Details ── */
