	top: 53mm;
	left: 132mm;
	font-size: 8.5pt;
}
.doc-date {
	top: 58.5mm;
	left: 132mm;
	font-size: 8.5pt;
}
.due-date {
	top: 70.5mm;
	left: 132mm;
	font-size: 8.5pt;
}
.terms {
	top: 75mm;
	left: 132mm;
	font-size: 8.5pt;
}
.incoterm {
	top: 88mm;
	left: 132mm;
	width: 70mm;
	font-size: 10pt;
}

/* ── Items (Columns) ── */
.col-no {
	left: 14mm;
	width: 11mm;
	font-size: 9pt;
}
.col-desc {
	left: 26mm;
	width: 76mm;
	font-size: 8.5pt;
	overflow: hidden;
	white-space: nowrap;
}
.col-wh {
	left: 102mm;
	width: 9mm;
	font-size: 8pt;
}
