/* ── Footer / Totals ── */
.remarks {
	top: 232mm;
	left: 14mm;
	width: 90mm;
	font-size: 8.5pt;
}
.total {
	top: 215mm;
	left: 176.5mm;
	width: 26mm;
	font-size: 9.5pt;
}
