.page,
.page * {
	font-family: "THSarabun", "Sarabun", Arial, sans-serif !important;
	font-weight: 400 !important;
}

html:
{%- set co = frappe.db.get_value("Company", doc.company, ["company_name", "company_logo", "tax_id", "phone_no", "website"], as_dict=True) -%}
{%- set print_pages = ['ต้นฉบับ/Original', 'สำเนา/Copy'] -%}
{%- set company_address = doc.get("billing_address_display") or doc.get("company_address_display") or "" -%}
{%- set items = doc.get("items") or [] -%}
{%- set page_size = 14 -%}
{%- set total_item_pages = ((items|length) / page_size)|round(0, 'ceil')|int if items|length else 1 -%}
{%- for page_title in print_pages -%}
{%- set copy_loop = loop -%}
{%- for item_page in range(total_item_pages) -%}
{%- set page_items = items[item_page * page_size:(item_page + 1) * page_size] -%}
<div class="page{% if copy_loop.last and loop.last %} last-page{% endif %}">
  <div class="f tc copy-label">{{ page_title }}{% if total_item_pages > 1 %} {{ item_page + 1 }}/{{ total_item_pages }}{% endif %}</div>
  {%- if company_address %}<div class="f company-address">{{ company_address }}</div>{%- endif %}
  <div class="f supplier-code">{{ doc.supplier or "" }}</div>
  <div class="f party-name">{{ doc.supplier_name or "" }}</div>
  {%- if doc.address_display %}<div class="f party-address">{{ doc.address_display }}</div>{%- endif %}
  <div class="f reference">{{ doc.order_confirmation_no or "" }}</div>
  <div class="f doc-no">{{ doc.name }}</div>
  <div class="f doc-date">{%- if doc.transaction_date %}{%- set d = (doc.transaction_date|string).split(' ')[0].split('-') -%}{{ d[2] }}/{{ d[1] }}/{{ ((d[0]|int)|string)[-4:] }}{%- endif %}</div>
  <div class="f due-date">{%- if doc.schedule_date %}{%- set sd = (doc.schedule_date|string).split(' ')[0].split('-') -%}{{ sd[2] }}/{{ sd[1] }}/{{ ((sd[0]|int)|string)[-4:] }}{%- endif %}</div>
  <div class="f terms">{{ doc.payment_terms_template or "" }}</div>
  <div class="f incoterm">{{ doc.incoterm or "" }}{%- if doc.named_place %} {{ doc.named_place }}{%- endif %}</div>
  {%- for item in page_items -%}
  {%- set rt = 101.0 + loop.index0 * 8.0 -%}
  <div class="f tc col-no" style="top:{{ '%.1f'|format(rt) }}mm;">{{ item_page * page_size + loop.index }}</div>
  <div class="f col-desc" style="top:{{ '%.1f'|format(rt) }}mm;"><span>{{ item.item_code or "" }}: </span>{%- if item.item_name and item.item_name != item.item_code %} {{ item.item_name }}{%- endif %}</div>
  <div class="f tc col-wh" style="top:{{ '%.1f'|format(rt) }}mm;">{{ (item.warehouse or "").split(" - ")[0] }}</div>
  <div class="f tr col-qty" style="top:{{ '%.1f'|format(rt) }}mm;">{{ "%g"|format(item.qty or 0) }} {{ item.uom or "" }}</div>
  <div class="f tr col-rate" style="top:{{ '%.1f'|format(rt) }}mm;">{{ print_currency(item.rate or 0, currency=doc.currency) }}</div>
  <div class="f tr col-disc" style="top:{{ '%.1f'|format(rt) }}mm;">{{ ("%g"|format(item.discount_percentage)) + "%" if item.discount_percentage else "" }}</div>
  <div class="f tr col-amount" style="top:{{ '%.1f'|format(rt) }}mm;">{{ print_currency(item.amount or 0, currency=doc.currency) }}</div>
  {%- endfor -%}
  {%- if loop.last -%}
  <div class="f remarks">{{ doc.terms or "" }}</div>
  <div class="f tr total">{{ print_currency(doc.total or 0, currency=doc.currency) }}</div>
  <div class="f tr discount">{{ print_currency(doc.discount_amount or 0, currency=doc.currency) }}</div>
  <div class="f tr net">{{ print_currency(doc.net_total or 0, currency=doc.currency) }}</div>
  <div class="f tr vat">{{ print_currency(doc.total_taxes_and_charges or 0, currency=doc.currency) }}</div>
  <div class="f tr grand">{{ print_currency(doc.rounded_total or doc.grand_total or 0, currency=doc.currency) }}</div>
  <div class="f amount-words">({{ number_to_thai_currency(doc.grand_total or 0, doc.currency) }}).</div>
  {%- endif -%}
</div>
{%- endfor -%}
{%- endfor -%}
